SELECT json_build_object('player_id',p.user_id,'profile_version',p.version,'selected_class',p.selected_class,'gold',w.gold,'potions',c.health_potion_count,'total_shop_rows',(SELECT count(*) FROM shop_purchases WHERE player_id=p.user_id),'total_price',(SELECT sum(price_gold) FROM shop_purchases WHERE player_id=p.user_id),'lost_rows',(SELECT count(*) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-c4977619fad8ff13a8d4dff2b0e257e0'),'lost_quantity',(SELECT sum(quantity) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-c4977619fad8ff13a8d4dff2b0e257e0'),'lost_price',(SELECT sum(price_gold) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-c4977619fad8ff13a8d4dff2b0e257e0'),'lost_ledger_rows',(SELECT count(*) FROM economy_ledger WHERE player_id=p.user_id AND request_id='godot-c4977619fad8ff13a8d4dff2b0e257e0' AND currency='Gold'),'lost_ledger_delta',(SELECT sum(delta) FROM economy_ledger WHERE player_id=p.user_id AND request_id='godot-c4977619fad8ff13a8d4dff2b0e257e0' AND currency='Gold'),'overlap_rows',(SELECT count(*) FROM shop_purchases WHERE player_id=p.user_id AND request_id='godot-ca1ae228347c8fd0fdddd518cdac4351'),'other_gold',(SELECT gold FROM player_wallets WHERE player_id='01a12db6-c466-73b1-b784-487d3eae66e2'),'other_potions',(SELECT health_potion_count FROM player_consumables WHERE player_id='01a12db6-c466-73b1-b784-487d3eae66e2')) FROM players p JOIN player_wallets w ON w.player_id=p.user_id JOIN player_consumables c ON c.player_id=p.user_id WHERE p.user_id='01a12db6-c21f-768e-bc27-981c8e377994'
